BEGIN;
SELECT no_plan();
UPDATE private.lifecycle_delivery_controls SET enabled=TRUE WHERE component IN ('deletion_intake','deletion_reconcile');
DELETE FROM private.billing_application_cutovers;
INSERT INTO private.lifecycle_requests(user_id,state,snapshot_captured) VALUES('bc000000-0000-4000-8000-000000000001','requested',TRUE);
INSERT INTO public.account_deletion_jobs(user_id,status,claim_token) VALUES('bc000000-0000-4000-8000-000000000001','in_progress','bd000000-0000-4000-8000-000000000001');
CREATE FUNCTION pg_temp.truth_start() RETURNS JSONB LANGUAGE sql AS $$
 SELECT public.begin_final_billing_verification('bc000000-0000-4000-8000-000000000001','bd000000-0000-4000-8000-000000000001'); $$;
CREATE FUNCTION pg_temp.truth_finish(outcome TEXT DEFAULT 'clear') RETURNS BOOLEAN LANGUAGE sql AS $$
 SELECT public.finish_final_billing_verification('bc000000-0000-4000-8000-000000000001','bd000000-0000-4000-8000-000000000001',(SELECT token FROM private.final_billing_verifications WHERE user_id='bc000000-0000-4000-8000-000000000001'),outcome); $$;
CREATE FUNCTION pg_temp.truth_authorize() RETURNS BOOLEAN LANGUAGE sql AS $$
 SELECT public.authorize_account_auth_delete('bc000000-0000-4000-8000-000000000001','bd000000-0000-4000-8000-000000000001'); $$;
SELECT is(pg_temp.truth_start()->>'status','provider_wait','both new routes without authoritative cutover fail closed');
SELECT ok(NOT pg_temp.truth_authorize(),'no timestamp cannot authorize');
SELECT throws_ok($$SELECT public.confirm_billing_application_cutover(repeat('a',64),NULL,'new checkout old portal')$$,'23502',NULL,'checkout-only evidence rejected');
SELECT throws_ok($$SELECT public.confirm_billing_application_cutover(NULL,repeat('b',64),'old checkout new portal')$$,'23502',NULL,'portal-only evidence rejected');
SELECT public.confirm_billing_application_cutover(repeat('a',64),repeat('b',64),'synthetic complete route evidence');
SELECT is(pg_temp.truth_start()->>'status','provider_wait','incomplete legacy horizon denied');
UPDATE private.billing_application_cutovers SET confirmed_at=clock_timestamp()-INTERVAL '25 hours';
UPDATE private.lifecycle_requests SET state='prepared' WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT is(pg_temp.truth_start()->>'status','checking','elapsed horizon permits lookup only');
SELECT ok(NOT pg_temp.truth_finish('provider_wait'),'provider unavailability never clears');
SELECT ok(NOT pg_temp.truth_authorize(),'elapsed horizon plus unavailable truth denied');
SELECT pg_temp.truth_start();
SELECT ok(pg_temp.truth_finish(),'fresh clear accepted');
SELECT throws_ok($$INSERT INTO private.provider_initiations(user_id,operation,fingerprint) VALUES('bc000000-0000-4000-8000-000000000001','checkout','synthetic')$$,'55000','Final billing verification in progress','new checkout serialized against authoritative proof');
SELECT throws_ok($$INSERT INTO private.provider_initiations(user_id,operation,fingerprint) VALUES('bc000000-0000-4000-8000-000000000001','portal','synthetic')$$,'55000','Final billing verification in progress','new portal serialized against authoritative proof');
SELECT pg_temp.truth_start();
SELECT ok(NOT pg_temp.truth_authorize(),'new lookup cannot reuse earlier clear');
SELECT pg_temp.truth_finish('provider_wait');
INSERT INTO private.provider_initiations(user_id,operation,fingerprint,state) VALUES('bc000000-0000-4000-8000-000000000001','checkout','synthetic','reconciled');
SELECT pg_temp.truth_start(); SELECT pg_temp.truth_finish();
UPDATE private.provider_initiations SET state='unresolved' WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT ok(NOT pg_temp.truth_authorize(),'checkout reservation change invalidates clear');
SELECT is(pg_temp.truth_start()->>'status','provider_wait','unresolved checkout blocks next verification');
UPDATE private.provider_initiations SET state='reconciled',operation='portal' WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT pg_temp.truth_start(); SELECT pg_temp.truth_finish();
UPDATE private.provider_initiations SET state='unresolved' WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT ok(NOT pg_temp.truth_authorize(),'portal reservation change invalidates clear');
UPDATE private.provider_initiations SET state='reconciled' WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT pg_temp.truth_start(); SELECT pg_temp.truth_finish();
INSERT INTO private.provider_assets(user_id,provider_id) VALUES('bc000000-0000-4000-8000-000000000001','cus_matrix');
SELECT ok(NOT pg_temp.truth_authorize(),'provider generation changes invalidate clear');
SELECT pg_temp.truth_start(); SELECT pg_temp.truth_finish();
SELECT private.capture_provider_obligation('bc000000-0000-4000-8000-000000000001','stripe_cleanup','cus_matrix','deletion:'||(SELECT generation::text FROM private.lifecycle_requests WHERE user_id='bc000000-0000-4000-8000-000000000001'));
SELECT ok(NOT pg_temp.truth_authorize(),'new unresolved task invalidates clear');
SELECT is(pg_temp.truth_start()->>'status','provider_wait','unresolved provider task blocks next lookup');
UPDATE private.lifecycle_work SET state='completed',completed_at=clock_timestamp() WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT pg_temp.truth_start(); SELECT pg_temp.truth_finish();
UPDATE public.account_deletion_jobs SET claim_token=gen_random_uuid() WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT ok(NOT pg_temp.truth_authorize(),'changed claim invalidates clear');
UPDATE public.account_deletion_jobs SET claim_token='bd000000-0000-4000-8000-000000000001' WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT pg_temp.truth_start(); SELECT pg_temp.truth_finish();
UPDATE private.lifecycle_requests SET generation=gen_random_uuid() WHERE user_id='bc000000-0000-4000-8000-000000000001';
SELECT ok(NOT pg_temp.truth_authorize(),'changed deletion generation invalidates clear');
SELECT pg_temp.truth_start(); SELECT pg_temp.truth_finish();
SELECT ok(pg_temp.truth_authorize(),'final stable verified state authorizes');
SELECT ok(NOT pg_temp.truth_authorize(),'consumed proof cannot authorize twice');
SELECT * FROM finish();
ROLLBACK;
